windowclass.script:
function updateVisibility()
	local sName = name.getValue();
	local sUpperName = string.upper(sName);

	-- Handle Singing width overrides first
	local baseWidth = 85;
	if sName == "Singing" then
		baseWidth = 60;
		voi_score.setVisible(true);
	else
		voi_score.setVisible(false);
	end

	-- Handle Dodge and Shock formatting (Indent text 10px, keep frame graphic stationary)
	-- Default state: left=3, width=85, frame="fielddark", 7,5,7,5. 
	-- Frame graphic left edge = 3 - 7 = -4. Frame graphic right edge = 3 + 85 + 7 = 95.

	if sUpperName == "DODGE" or sUpperName == "SHOCK" then
		if sName ~= sUpperName then
			name.setValue(sUpperName); -- Force uppercase
		end

		name.setFont("harn_skill_12");

		-- Move control bounds 10px right (3 -> 13)
		-- name.setAnchor("left", "", "left", "absolute", 13);
		-- name.setAnchoredWidth(baseWidth - 10);

		-- Stretch the graphic backwards by 10px so it still renders at -4 and 95
		-- Left frame offset: 7 + 10 = 17
		-- Right frame offset: 7 + 10 = 17
		-- name.setFrame("fielddark", 17, 5, 17, 5);

	else
		-- Revert to normal
		name.setFont("sheettext");
		name.setAnchor("left", "", "left", "absolute", 3);
		name.setAnchoredWidth(baseWidth);
		name.setFrame("fielddark", 7, 5, 7, 5);
	end
end

-- Logic to dynamically link SM to a parent skill
local sParentNodePath = "";
function onInit()
	-- Add handlers for name update
	local node = getDatabaseNode();
	if node then
		DB.addHandler(node.getPath() .. ".name", "onUpdate", onNameUpdate);
	end
	updateVisibility();
	linkDynamicSM();
end

function onClose()
	local node = getDatabaseNode();
	if node then
		DB.removeHandler(node.getPath() .. ".name", "onUpdate", onNameUpdate);
	end
	if sParentNodePath ~= "" then
		DB.removeHandler(sParentNodePath .. ".sm", "onUpdate", onParentSMUpdate);
	end
end

function linkDynamicSM()
	local sUpperName = string.upper(name.getValue());
	local nodeChar = windowlist.window.getDatabaseNode();
	if not nodeChar then return; end

	local sTargetParentName = "";
	if sUpperName == "DODGE" then
		sTargetParentName = "Melee";
	elseif sUpperName == "SHOCK" then
		sTargetParentName = "Initiative";
	end

	if sTargetParentName ~= "" then
		-- Search combatskills for the parent
		local nodeCombatList = DB.getChild(nodeChar, "combatskills");
		if nodeCombatList then
			for _, nodeSkill in pairs(DB.getChildren(nodeCombatList)) do
				if DB.getValue(nodeSkill, "name", "") == sTargetParentName then
					-- Found the parent, set up a handler on its SM
					sParentNodePath = nodeSkill.getPath();
					DB.addHandler(sParentNodePath .. ".sm", "onUpdate", onParentSMUpdate);
					onParentSMUpdate(); -- Initial sync
					return;
				end
			end
		end
	end
end

function onParentSMUpdate()
	if sParentNodePath ~= "" then
		local nParentSM = DB.getValue(sParentNodePath .. ".sm", 0);
		local nodeThis = getDatabaseNode();
		if nodeThis then
			DB.setValue(nodeThis, "sm", "number", nParentSM);
		end
	end
end

function onNameUpdate()
	updateVisibility();
	-- Resync dynamic anchors if name changes
	if sParentNodePath ~= "" then
		DB.removeHandler(sParentNodePath .. ".sm", "onUpdate", onParentSMUpdate);
		sParentNodePath = "";
	end
	linkDynamicSM();
end

function setCustomEditMode(bEdit)
	btn_recalc.setVisible(bEdit);

	if bEdit then
		local sNameVal = name.getValue();
		local bDeletable = false;
		if SkillsData then
			local rSkill = SkillsData.getSkill(sNameVal);
			if rSkill then
				if rSkill.sm == 0 and sNameVal ~= "Language" and sNameVal ~= "Ritual" then
					bDeletable = true;
				end
			else
				bDeletable = true;
			end
		else
			bDeletable = true;
		end

		btn_delete.setVisible(bDeletable);
	else
		btn_delete.setVisible(false);
	end
end

stringfield.script:
function onLoseFocus()
	local sName = getValue();
	if sName == "" then return; end

	Debug.console("Skill name entered: " .. sName);

	-- Look up skill data from database
	local nodeSkillsRef = DB.findNode("harnmaster.skills");
	if nodeSkillsRef then
		for _, nodeRefSkill in pairs(DB.getChildren(nodeSkillsRef)) do
			if DB.getValue(nodeRefSkill, "name", "") == sName then
				local sAtt1 = DB.getValue(nodeRefSkill, "att1", "");
				local sAtt2 = DB.getValue(nodeRefSkill, "att2", "");
				local nSM = DB.getValue(nodeRefSkill, "sm", 0);

				Debug.console("Found skill data: att1=" .. sAtt1 .. ", att2=" .. sAtt2 .. ", sm=" .. tostring(nSM));

				-- Update att1, att2, sm fields in character's skill entry
				local nodeCharSkill = window.getDatabaseNode();
				if nodeCharSkill then
					Debug.console("Setting database values for: " .. nodeCharSkill.getPath());
					DB.setValue(nodeCharSkill, "att1", "string", sAtt1);
					DB.setValue(nodeCharSkill, "att2", "string", sAtt2);
					DB.setValue(nodeCharSkill, "sm", "number", nSM);

					-- Calculate SB from character attributes
					-- Navigate to character node (skill -> skilllist -> character)
					local nodeChar = nodeCharSkill.getParent().getParent();
					if nodeChar then
						-- Get attribute scores (field names are lowercase + "_score")
						local sAtt1Field = string.lower(sAtt1) .. "_score";
						local sAtt2Field = string.lower(sAtt2) .. "_score";
						local nAtt1Value = DB.getValue(nodeChar, sAtt1Field, 0);
						local nAtt2Value = DB.getValue(nodeChar, sAtt2Field, 0);

						Debug.console("Attribute values: " .. sAtt1 .. "=" .. tostring(nAtt1Value) .. ", " .. sAtt2 .. "=" .. tostring(nAtt2Value));

						-- Calculate SB: average, round up if att1 > att2, else round down
						local nSB = 0;
						if nAtt1Value > 0 or nAtt2Value > 0 then
							local nAvg = (nAtt1Value + nAtt2Value) / 2;
							if nAtt1Value > nAtt2Value then
								nSB = math.ceil(nAvg);
							else
								nSB = math.floor(nAvg);
							end
						end

						Debug.console("Calculated SB: " .. tostring(nSB));
						DB.setValue(nodeCharSkill, "sb", "number", nSB);
					else
						Debug.console("ERROR: Could not get character node");
					end
				else
					Debug.console("ERROR: Could not get database node");
				end
				return;
			end
		end
		Debug.console("Skill not found in harnmaster.skills: " .. sName);
	else
		Debug.console("ERROR: harnmaster.skills node not found");
	end
	window.updateVisibility();
end

numberfield.script:
function onInit()
	-- Set up DB handler to sync from character's voi_score
	local nodeChar = window.getDatabaseNode().getParent().getParent();
	if nodeChar then
		local nodeVoi = DB.getPath(nodeChar, "voi_score");
		DB.addHandler(nodeVoi, "onUpdate", onVoiUpdated);
		onVoiUpdated(); -- initial sync
	end
end

function onClose()
	local nodeChar = window.getDatabaseNode().getParent().getParent();
	if nodeChar then
		local nodeVoi = DB.getPath(nodeChar, "voi_score");
		DB.removeHandler(nodeVoi, "onUpdate", onVoiUpdated);
	end
end

function onVoiUpdated()
	local nodeChar = window.getDatabaseNode().getParent().getParent();
	if nodeChar then
		local nVoi = DB.getValue(nodeChar, "voi_score", 0);
		if getValue() ~= nVoi then
			setValue(nVoi);
		end
	end
end

function onValueChanged()
	local nVal = getValue();
	if nVal > 25 then
		nVal = 25;
		setValue(25);
	elseif nVal < 1 and nVal ~= 0 then
		nVal = 1;
		setValue(1);
	end

	-- Sync back to character's global voi_score
	local nodeChar = window.getDatabaseNode().getParent().getParent();
	if nodeChar then
		DB.setValue(nodeChar, "voi_score", "number", nVal);
	end
end

function onValueChanged()
	local nVal = getValue();
	if type(nVal) ~= "number" then
		nVal = 0;
	end
	if nVal > 5 then
		setValue(5);
	elseif nVal < 0 then
		setValue(0);
	end
end

buttoncontrol.script:
function onButtonPress()
	local nodeBase = window.getDatabaseNode();
	if nodeBase then
		local nSM = DB.getValue(nodeBase, "sm", 0);
		local nSB = DB.getValue(nodeBase, "sb", 0);
		local nML = nSM * nSB;
		DB.setValue(nodeBase, "ml", "number", nML);
	end
end

function onButtonPress()
	local nodeBase = window.getDatabaseNode();
	if nodeBase then
		nodeBase.delete();
	end
end

windowclass.script:
-- Helper function to check if a skill already exists in a list
function skillExists(nodeSkillList, sSkillName)
	if not nodeSkillList then return false; end
	for _, nodeSkill in pairs(DB.getChildren(nodeSkillList)) do
		if DB.getValue(nodeSkill, "name", "") == sSkillName then
			return true;
		end
	end
	return false;
end

function onRefresh()
	local nodeChar = getDatabaseNode();
	if nodeChar and SkillsManager and SkillsManager.recalculateAllSB then
		SkillsManager.recalculateAllSB(nodeChar);
	end

	-- Iterate through all skill lists and force entries to update their special fields
	local tLists = { socialskills, loreskills, physicalskills, natureskills, craftskills, combatskills };
	for _, list in ipairs(tLists) do
		for _, window in pairs(list.getWindows()) do
			if window.onNameUpdate then
				window.onNameUpdate();
			end
			if window.onLanguageUpdate then
				window.onLanguageUpdate();
			end
		end
	end

	-- Update sunsign modifiers in category labels
	updateCategoryLabels();
end

function updateCategoryLabels()
	local nodeChar = getDatabaseNode();
	if not nodeChar then return; end

	local sSunsign = DB.getValue(nodeChar, "birth_sunsign", "");
	local tMods = HarnManager.getSunsignModifiers(sSunsign);
	-- tMods is {social, lore, physical, nature, craft, combat}

	local function formatMod(n)
		if n > 0 then return "[+" .. n .. "]"; end
		if 0 > n then return "[" .. n .. "]"; end
		return "[0]";
	end

	if social_title then
		social_title.setValue(Interface.getString("harn_skill_social") .. " " .. formatMod(tMods[1]));
	end
	if lore_title then
		lore_title.setValue(Interface.getString("harn_skill_lore") .. " " .. formatMod(tMods[2]));
	end
	if physical_title then
		physical_title.setValue(Interface.getString("harn_skill_physical") .. " " .. formatMod(tMods[3]));
	end
	if nature_title then
		nature_title.setValue(Interface.getString("harn_skill_nature") .. " " .. formatMod(tMods[4]));
	end
	if craft_title then
		craft_title.setValue(Interface.getString("harn_skill_craft") .. " " .. formatMod(tMods[5]));
	end
	if combat_title then
		combat_title.setValue(Interface.getString("harn_skill_combat") .. " " .. formatMod(tMods[6]));
	end
end

function onInit()
	-- Auto-populate default skills (sm > 0) for new characters
	local nodeChar = getDatabaseNode();
	if nodeChar then
		DB.addHandler(nodeChar.getPath() .. ".birth_sunsign", "onUpdate", updateCategoryLabels);
	end
	updateCategoryLabels();
	if not nodeChar then return; end

	-- Check if skills have already been initialized using a flag
	local bInitialized = DB.getValue(nodeChar, "skills_initialized", 0);
	if bInitialized == 1 then
		Debug.console("Skills already initialized, skipping auto-populate");
		return;
	end

	-- Set the flag immediately to prevent duplicate runs
	DB.setValue(nodeChar, "skills_initialized", "number", 1);

	Debug.console("Auto-populating default skills for new character");

	-- Group to datasource mapping
	local tGroupMap = {
		["Social"] = "socialskills",
		["Lore"] = "loreskills",
		["Physical"] = "physicalskills",
		["Nature"] = "natureskills",
		["Craft"] = "craftskills",
		["Combat"] = "combatskills"
	};

	-- Get skills reference from database
	local nodeSkillsRef = DB.findNode("harnmaster.skills");
	if not nodeSkillsRef then
		Debug.console("ERROR: harnmaster.skills not found");
		return;
	end

	-- Track skills we've already added this run to prevent duplicates
	local tAddedSkills = {};

	-- Skills to always include as defaults (even with SM=0)
	local tAlwaysInclude = {
		["Language"] = true,
		["Ritual"] = true
	};

	-- Iterate through all skills
	for _, nodeRefSkill in pairs(DB.getChildren(nodeSkillsRef)) do
		local sName = DB.getValue(nodeRefSkill, "name", "");
		local nSM = DB.getValue(nodeRefSkill, "sm", 0);
		if nSM > 0 or tAlwaysInclude[sName] then
			local sGroup = DB.getValue(nodeRefSkill, "group", "");
			local sAtt1 = DB.getValue(nodeRefSkill, "att1", "");
			local sAtt2 = DB.getValue(nodeRefSkill, "att2", "");

			-- Find the right skill list for this group
			local sListName = tGroupMap[sGroup];
			if sListName then
				-- Create a unique key for this skill
				local sKey = sListName .. ":" .. sName;

				-- Skip if we already added this skill in this run
				if tAddedSkills[sKey] then
					Debug.console("Skipping duplicate: " .. sName);
				else
					-- Also check if it exists in the database already
					local nodeSkillList = DB.createChild(nodeChar, sListName);
					if not skillExists(nodeSkillList, sName) then
						Debug.console("Adding default skill: " .. sName .. " to " .. sListName);

						local nodeNewSkill = DB.createChild(nodeSkillList);

						DB.setValue(nodeNewSkill, "name", "string", sName);
						DB.setValue(nodeNewSkill, "att1", "string", sAtt1);
						DB.setValue(nodeNewSkill, "att2", "string", sAtt2);
						DB.setValue(nodeNewSkill, "sm", "number", nSM);

						-- Calculate SB from character attributes
						local sAtt1Field = string.lower(sAtt1) .. "_score";
						local sAtt2Field = string.lower(sAtt2) .. "_score";
						local nAtt1Value = DB.getValue(nodeChar, sAtt1Field, 0);
						local nAtt2Value = DB.getValue(nodeChar, sAtt2Field, 0);

						local nSB = 0;
						if nAtt1Value > 0 or nAtt2Value > 0 then
							local nAvg = (nAtt1Value + nAtt2Value) / 2;
							if nAtt1Value > nAtt2Value then
								nSB = math.ceil(nAvg);
							else
								nSB = math.floor(nAvg);
							end
						end
						DB.setValue(nodeNewSkill, "sb", "number", nSB);

						-- Mark as added
						tAddedSkills[sKey] = true;
					else
						Debug.console("Skill already exists in DB: " .. sName);
					end
				end
			end
		end
	end

	Debug.console("Default skills auto-population complete");
end

function onClose()
	local nodeChar = getDatabaseNode();
	if nodeChar then
		DB.removeHandler(nodeChar.getPath() .. ".birth_sunsign", "onUpdate", updateCategoryLabels);
	end
end

