windowlist.script:
function onInit()
	-- Force an initial sort
	applySort();
end

function onListChanged()
	-- Ensure custom sorting happens when items are added/removed
	applySort();
end

function onSortCompare(w1, w2)
	local sName1 = w1.name.getValue();
	local sName2 = w2.name.getValue();

	local sKey1 = sName1:lower();
	local sKey2 = sName2:lower();

	-- Special case for DODGE (always follows Melee)
	if sKey1 == "dodge" then sKey1 = "melee~"; end
	if sKey2 == "dodge" then sKey2 = "melee~"; end

	-- Special case for SHOCK (always follows Initiative)
	if sKey1 == "shock" then sKey1 = "initiative~"; end
	if sKey2 == "shock" then sKey2 = "initiative~"; end

	-- Normal alphabetical sort
	if sKey1 == sKey2 then
		return false;
	end
	return sKey1 > sKey2;
end
